228: // statsCommand prints paired statistics for conditions A and D from stored records.
229: func statsCommand(args []string) {
230: 	flags := flag.NewFlagSet("stats", flag.ExitOnError)
231: 	output := flags.String("output", filepath.Join("BENCHMARK", "results", "pilot"), "results directory")
232: 	if err := flags.Parse(args); err != nil {
233: 		os.Exit(2)
234: 	}
235: 	data, err := os.ReadFile(filepath.Join(*output, "RESULTS.json"))
236: 	if err != nil {
237: 		fmt.Fprintln(os.Stderr, err)
238: 		os.Exit(1)
239: 	}
240: 	var records []runner.RunRecord
241: 	if err := json.Unmarshal(data, &records); err != nil {
242: 		fmt.Fprintln(os.Stderr, err)
243: 		os.Exit(1)
244: 	}
245: 	type key struct{ model, task string }
246: 	pairs := make(map[key]map[string]runner.RunRecord)
247: 	for _, record := range records {
248: 		k := key{model: record.Model, task: record.TaskID}
249: 		if pairs[k] == nil {
250: 			pairs[k] = make(map[string]runner.RunRecord)
251: 		}
252: 		pairs[k][record.Condition] = record
253: 	}
254: 
255: 	metrics := []struct {
256: 		name  string
257: 		value func(runner.RunRecord) float64
258: 	}{
259: 		{"input tokens", func(r runner.RunRecord) float64 { return float64(r.Tokens.Input) }},
260: 		{"output tokens", func(r runner.RunRecord) float64 { return float64(r.Tokens.Output) }},
261: 		{"reasoning tokens", func(r runner.RunRecord) float64 { return float64(r.Tokens.Reasoning) }},
262: 		{"cache read", func(r runner.RunRecord) float64 { return float64(r.Tokens.CacheRead) }},
263: 		{"duration ms", func(r runner.RunRecord) float64 { return float64(r.DurationMS) }},
264: 		{"tool calls", func(r runner.RunRecord) float64 { return float64(r.ToolCalls) }},
265: 	}
266: 	for _, metric := range metrics {
267: 		samples := make([]stats.PairedSample, 0)
268: 		for k, byCondition := range pairs {
269: 			a, hasA := byCondition["A"]
270: 			d, hasD := byCondition["D"]
271: 			if !hasA || !hasD {
272: 				continue
273: 			}
274: 			samples = append(samples, stats.PairedSample{
275: 				ID: k.model + "/" + k.task,
276: 				A:  metric.value(a),
277: 				B:  metric.value(d),
278: 			})
279: 		}
280: 		result := stats.Paired(samples)
281: 		fmt.Printf("%-18s n=%d meanA=%10.2f meanD=%10.2f diff=%10.2f CI=[%10.2f, %10.2f] p=%.4f d=%.3f\n",
282: 			metric.name, result.N, result.MeanA, result.MeanB, result.MeanDiff,
283: 			result.CILow, result.CIHigh, result.PApprox, result.CohensD)
284: 	}
285: }
