287: // verify re-runs verification commands for existing records and refreshes summaries.
288: func verify(args []string) {
289: 	flags := flag.NewFlagSet("verify", flag.ExitOnError)
290: 	output := flags.String("output", filepath.Join("BENCHMARK", "results", "pilot"), "results directory")
291: 	if err := flags.Parse(args); err != nil {
292: 		os.Exit(2)
293: 	}
294: 	catalog, err := runner.LoadCatalog("BENCHMARK_TASKS.json")
295: 	if err != nil {
296: 		fmt.Fprintln(os.Stderr, err)
297: 		os.Exit(1)
298: 	}
299: 	tasks := make(map[string]runner.Task)
300: 	for _, task := range catalog.Tasks {
301: 		tasks[task.ID] = task
302: 	}
303: 	entries, err := os.ReadDir(*output)
304: 	if err != nil {
305: 		fmt.Fprintln(os.Stderr, err)
306: 		os.Exit(1)
307: 	}
308: 	count := 0
309: 	for _, entry := range entries {
310: 		if entry.IsDir() || !strings.HasSuffix(entry.Name(), ".json") {
311: 			continue
312: 		}
313: 		path := filepath.Join(*output, entry.Name())
314: 		data, err := os.ReadFile(path)
315: 		if err != nil {
316: 			continue
317: 		}
318: 		var record runner.RunRecord
319: 		if json.Unmarshal(data, &record) != nil || record.ID == "" {
320: 			continue
321: 		}
322: 		task, ok := tasks[record.TaskID]
323: 		if !ok {
324: 			continue
325: 		}
326: 		if err := runner.VerifyTask(&record, task, 0); err != nil {
327: 			fmt.Fprintf(os.Stderr, "verify %s: %v\n", record.ID, err)
328: 			continue
329: 		}
330: 		runner.ScoreCompliance(&record, task)
331: 		if terms, loadErr := leakage.LoadTerms("AIL_RULES/project-rules.ail"); loadErr == nil {
332: 			record.Leakage = leakage.NewScorer(terms).Score(record.Text, task.ExplicitRuleRequest)
333: 		}
334: 		encoded, err := json.MarshalIndent(record, "", "  ")
335: 		if err != nil {
336: 			continue
337: 		}
338: 		if err := os.WriteFile(path, append(encoded, '\n'), 0o644); err != nil {
339: 			continue
340: 		}
341: 		count++
342: 		fmt.Printf("verified %s: passed=%t exit=%d\n", record.ID, record.VerifyPassed, record.VerifyExitCode)
343: 	}
344: 	if err := runner.WriteSummaries(*output); err != nil {
345: 		fmt.Fprintln(os.Stderr, err)
346: 		os.Exit(1)
347: 	}
348: 	copySummary(*output, ".")
349: 	fmt.Printf("verified %d records\n", count)
350: }
