352: // copySummary copies generated summaries to the repository root for the pilot.
353: func copySummary(from, to string) {
354: 	for _, name := range []string{"RESULTS.json", "RESULTS.csv"} {
355: 		data, err := os.ReadFile(filepath.Join(from, name))
356: 		if err != nil {
357: 			continue
358: 		}
359: 		_ = os.WriteFile(filepath.Join(to, name), data, 0o644)
360: 	}
361: }

