391: // RunOne executes a single task and persists its record. Completed successful runs are skipped.
392: func RunOne(request Request) (RunRecord, error) {
393: 	if err := os.MkdirAll(request.OutputDir, 0o755); err != nil {
394: 		return RunRecord{}, err
395: 	}
396: 	id := fmt.Sprintf("%s__%s__%s__%s", request.Condition, request.Task.ID, sanitize(request.Model.ID), request.Format)
